import fs from "node:fs";
import path from "node:path";
import { buildSchemas, schemaFiles } from "../domain/build.ts";
import { USAGE } from "../prompts.ts";

const opt = (argv: string[], name: string): string | undefined => {
  const at = argv.indexOf(name);
  return at < 0 ? undefined : argv[at + 1];
};

export const installedBundle = (): string => {
  const bin = Bun.which("claude");
  if (!bin) throw new Error("claude is not on PATH.");
  const platformBin = path.join(
    path.dirname(bin),
    "..",
    "install",
    "global",
    "node_modules",
    "@anthropic-ai",
    `claude-code-${process.platform}-${process.arch}`,
    "claude",
  );
  return fs.existsSync(platformBin) ? platformBin : fs.realpathSync(bin);
};

export const versionOf = (bundle: string): string => {
  const base = path.basename(bundle);
  if (/^\d+\.\d+\.\d+$/.test(base)) return base;
  const r = Bun.spawnSync([bundle, "--version"]);
  if (r.exitCode !== 0)
    throw new Error(`${bundle} --version exited with ${r.exitCode}.`);
  return /\d+\.\d+\.\d+/.exec(r.stdout.toString())?.[0] ?? "unknown";
};

export const main = async (argv: string[]): Promise<number> => {
  if (argv.includes("--help") || argv.includes("-h")) {
    console.log(USAGE);
    return 0;
  }
  const outDir = opt(argv, "--out");
  if (!outDir) {
    console.error(`schema: --out is required.\n${USAGE}`);
    return 2;
  }
  try {
    const given = opt(argv, "--bundle");
    const bundle = given ?? installedBundle();
    const asked = opt(argv, "--version");
    if (asked && !given) {
      const installed = versionOf(bundle);
      if (installed !== asked)
        throw new Error(
          `Claude Code ${asked} is not installed, the installed version is ${installed}`,
        );
    }
    const version = asked ?? versionOf(bundle);
    const src = Buffer.from(await Bun.file(bundle).arrayBuffer()).toString(
      "latin1",
    );
    const schemas = buildSchemas(src, version);
    const out = path.resolve(outDir);
    fs.mkdirSync(out, { recursive: true });
    const files = schemaFiles();
    for (const kind of ["user", "managed"] as const)
      await Bun.write(
        path.join(out, files[kind]),
        `${JSON.stringify(schemas[kind], null, 2)}\n`,
      );
    console.log(
      `Claude Code ${version}: ${Object.keys(schemas.user.properties ?? {}).length} top-level keys`,
    );
    for (const name of Object.values(files)) console.log(path.join(out, name));
    return 0;
  } catch (err) {
    console.error(`schema: ${(err as Error).message}`);
    return 1;
  }
};
